#!/usr/bin/env python3
"""Plan 001 Step 1: Throttled parallel API scoring.
9 models in parallel, global semaphore caps concurrent API calls.
Key fix: semaphore released between retries so failed models don't block others.
"""

import os
os.environ["HF_HOME"] = "/root/autodl-tmp/.hf_cache"
os.environ["HF_DATASETS_CACHE"] = "/root/autodl-tmp/.hf_cache/datasets"
os.environ["HF_HUB_CACHE"] = "/root/autodl-tmp/.hf_cache/hub"

import sys
sys.path.insert(0, "/root/cert_manip_resist_eval")

import json
import time
import traceback
import threading
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path
from datetime import datetime, timezone

from src.api_judge_service import _NO_TEMP_ZERO, _parse_judge_output_robust
from src.judge_service import PAIRWISE_SYSTEM_PROMPT, PAIRWISE_USER_TEMPLATE
from src.attacks import (
    PromptInjection, SycophancyExploitation, ScoreManipulation,
    VerbosityBias, PositionBias, AuthorityBias,
    apply_attack_to_pairs, apply_position_attack,
    measure_asr, measure_position_asr,
)
from src.utils import setup_logging

logger = setup_logging("plan001_step1_throttled")

API_KEY = "[REDACTED]"
API_BASE = "http://47.94.22.126/v1"

MODEL_IDS = [
    "claude-opus-4", "gpt-5.5", "gemini-2.5-pro", "gpt-4.1",
    "claude-sonnet-4", "gpt-4o", "gemini-2.5-flash", "gpt-4o-mini", "claude-3-haiku",
]
DATASETS = ["mmlu", "arc_challenge"]
ATTACK_DEFS = {
    "prompt_injection": PromptInjection(0),
    "sycophancy": SycophancyExploitation(seed=42),
    "score_manipulation": ScoreManipulation(0),
    "verbosity_bias": VerbosityBias(seed=42),
    "position_bias": PositionBias(),
    "authority_bias": AuthorityBias(seed=42),
}
ATTACK_NAMES = list(ATTACK_DEFS.keys())
CONDITIONS = ["clean"] + ATTACK_NAMES

RESULTS_DIR = Path("/root/cert_manip_resist_eval/artifacts/results/plan001")
SCORES_DIR = RESULTS_DIR / "individual_scores"

DRY_RUN = "--dry-run" in sys.argv
N_SAMPLES = 5 if DRY_RUN else 300
PER_MODEL_WORKERS = 5
GLOBAL_CONCURRENT = 10
MAX_RETRIES = 5
TIMEOUT = 90

_MODEL_MAX_TOKENS = {"gemini-2.5-pro": 2048, "gemini-2.5-flash": 2048}
DEFAULT_MAX_TOKENS = 512

global_sem = threading.Semaphore(GLOBAL_CONCURRENT)

_global_rps_lock = threading.Lock()
_global_last_call = 0.0
_GLOBAL_MIN_INTERVAL = 1.0 / 15.0  # 15 RPS global cap

_session = requests.Session()
_session.headers.update({
    "Content-Type": "application/json",
    "Authorization": [REDACTED]"Bearer {API_KEY}",
})


def global_rate_limit():
    global _global_last_call
    with _global_rps_lock:
        now = time.monotonic()
        wait = _GLOBAL_MIN_INTERVAL - (now - _global_last_call)
        if wait > 0:
            time.sleep(wait)
        _global_last_call = time.monotonic()


def _single_api_call(model_id, system_msg, user_msg):
    """One API attempt. Returns (success, result_dict)."""
    payload = {
        "model": model_id,
        "messages": [
            {"role": "system", "content": system_msg},
            {"role": "user", "content": user_msg},
        ],
        "max_tokens": _MODEL_MAX_TOKENS.get(model_id, DEFAULT_MAX_TOKENS),
    }
    if model_id not in _NO_TEMP_ZERO:
        payload["temperature"] = 0.0

    t0 = time.monotonic()
    try:
        resp = _session.post(f"{API_BASE}/chat/completions", json=payload, timeout=TIMEOUT)
        latency_ms = (time.monotonic() - t0) * 1000

        if resp.status_code == 200:
            data = resp.json()
            content = data["choices"][0]["message"]["content"]
            usage = data.get("usage", {})
            parsed = _parse_judge_output_robust(content)
            parsed["judge_id"] = model_id
            parsed["latency_ms"] = round(latency_ms, 1)
            parsed["input_tokens"] = usage.get("prompt_tokens", 0)
            parsed["output_tokens"] = usage.get("completion_tokens", 0)
            return True, parsed

        if resp.status_code in (429, 502, 503, 504) or resp.status_code >= 500:
            return False, {"error": f"HTTP {resp.status_code}", "retryable": True}

        return True, {"error": f"HTTP {resp.status_code}: {resp.text[:200]}", "judge_id": model_id}

    except requests.exceptions.Timeout:
        return False, {"error": "timeout", "retryable": True}
    except requests.exceptions.ConnectionError as e:
        return False, {"error": f"connection: {e}", "retryable": True}
    except Exception as e:
        return False, {"error": str(e), "retryable": False}


def guarded_score(model_id, question, response_a, response_b):
    """Score with global semaphore + retry. Semaphore released between retries."""
    user_msg = PAIRWISE_USER_TEMPLATE.format(
        question=question, response_a=response_a, response_b=response_b
    )

    for attempt in range(MAX_RETRIES):
        global_sem.acquire()
        try:
            global_rate_limit()
            success, result = _single_api_call(model_id, PAIRWISE_SYSTEM_PROMPT, user_msg)
        finally:
            global_sem.release()

        if success:
            return result

        if not result.get("retryable", False):
            result["judge_id"] = model_id
            return result

        wait = 2 ** attempt * 2  # 2, 4, 8, 16, 32
        logger.warning(f"{model_id} {result['error']}, retry {attempt+1}/{MAX_RETRIES} in {wait}s")
        time.sleep(wait)

    return {"error": "max_retries_exceeded", "judge_id": model_id}


def load_pairs():
    ckpt_path = Path("/root/cert_manip_resist_eval/artifacts/results/_taxonomy_checkpoint.json")
    logger.info(f"Loading pairs from {ckpt_path}")
    with open(ckpt_path) as f:
        data = json.load(f)
    pairs = {}
    for ds in DATASETS:
        ds_pairs = data["pairs"][ds][:N_SAMPLES]
        pairs[ds] = ds_pairs
        logger.info(f"  {ds}: {len(ds_pairs)} pairs loaded")
    return pairs


def ckpt_path(model_id, dataset, condition):
    return SCORES_DIR / f"{model_id}__{dataset}__{condition}.json"


def save_condition_result(model_id, dataset, condition, result):
    SCORES_DIR.mkdir(parents=True, exist_ok=True)
    path = ckpt_path(model_id, dataset, condition)
    with open(path, "w") as f:
        json.dump(result, f, ensure_ascii=False)
    logger.info(f"  [{model_id}] Saved: {path.name}")


def load_condition_result(model_id, dataset, condition):
    path = ckpt_path(model_id, dataset, condition)
    if path.exists():
        with open(path) as f:
            return json.load(f)
    return None


def is_done(model_id, dataset, condition):
    return ckpt_path(model_id, dataset, condition).exists()


def compute_accuracy(scores, pairs):
    correct = 0
    total = 0
    for s, p in zip(scores, pairs):
        if not isinstance(s, dict):
            continue
        winner = s.get("winner")
        if winner is None:
            continue
        total += 1
        if winner == p["ground_truth_winner"]:
            correct += 1
    return correct / max(total, 1), total


def batch_score(model_id, items, max_workers):
    results = [None] * len(items)
    with ThreadPoolExecutor(max_workers=max_workers) as pool:
        future_to_idx = {
            pool.submit(guarded_score, model_id,
                        it["question"], it["response_a"], it["response_b"]): i
            for i, it in enumerate(items)
        }
        for future in as_completed(future_to_idx):
            idx = future_to_idx[future]
            try:
                results[idx] = future.result()
            except Exception as e:
                results[idx] = {"error": str(e), "judge_id": model_id}
    return results


def score_condition(model_id, pairs, condition):
    if condition == "clean":
        items = [
            {"question": p["question"], "response_a": p["response_a"], "response_b": p["response_b"]}
            for p in pairs
        ]
        return batch_score(model_id, items, PER_MODEL_WORKERS), pairs

    attack = ATTACK_DEFS[condition]
    if condition == "position_bias":
        attacked_pairs = apply_position_attack(pairs)
    else:
        attacked_pairs = apply_attack_to_pairs(pairs, attack)

    items = [
        {"question": p["question"], "response_a": p["response_a"], "response_b": p["response_b"]}
        for p in attacked_pairs
    ]
    return batch_score(model_id, items, PER_MODEL_WORKERS), attacked_pairs


def run_model(model_id, all_pairs):
    logger.info(f"=== [{model_id}] START ===")
    model_results = {}
    model_t0 = time.time()
    conditions_done = 0

    for ds in DATASETS:
        pairs = all_pairs[ds]
        ds_results = {}

        if is_done(model_id, ds, "clean"):
            logger.info(f"  [{model_id}][{ds}] clean: SKIP")
            clean_result = load_condition_result(model_id, ds, "clean")
        else:
            logger.info(f"  [{model_id}][{ds}] clean: scoring {len(pairs)} pairs...")
            t0 = time.time()
            clean_scores, _ = score_condition(model_id, pairs, "clean")
            elapsed = time.time() - t0
            acc, n_valid = compute_accuracy(clean_scores, pairs)
            n_errors = sum(1 for s in clean_scores if isinstance(s, dict) and s.get("error"))
            clean_result = {
                "condition": "clean",
                "scores": clean_scores,
                "accuracy": round(acc, 4),
                "n_samples": len(pairs),
                "n_valid": n_valid,
                "n_errors": n_errors,
                "elapsed_s": round(elapsed, 1),
            }
            save_condition_result(model_id, ds, "clean", clean_result)
            conditions_done += 1
            logger.info(f"  [{model_id}][{ds}] clean: acc={acc:.3f}, errors={n_errors}, {elapsed:.0f}s")

        ds_results["clean"] = {
            "accuracy": clean_result["accuracy"],
            "n_samples": clean_result["n_samples"],
            "n_errors": clean_result.get("n_errors", 0),
        }
        clean_scores = clean_result["scores"]

        for atk_name in ATTACK_NAMES:
            if is_done(model_id, ds, atk_name):
                logger.info(f"  [{model_id}][{ds}] {atk_name}: SKIP")
                atk_result = load_condition_result(model_id, ds, atk_name)
            else:
                logger.info(f"  [{model_id}][{ds}] {atk_name}: scoring {len(pairs)} pairs...")
                t0 = time.time()
                try:
                    atk_scores, atk_pairs = score_condition(model_id, pairs, atk_name)
                    elapsed = time.time() - t0

                    if atk_name == "position_bias":
                        asr = measure_position_asr(clean_scores, atk_scores, pairs, atk_pairs)
                    else:
                        asr = measure_asr(clean_scores, atk_scores, pairs)

                    n_errors = sum(1 for s in atk_scores if isinstance(s, dict) and s.get("error"))
                    atk_result = {
                        "condition": atk_name,
                        "scores": atk_scores,
                        "asr": round(asr, 4),
                        "n_samples": len(pairs),
                        "n_valid": sum(1 for s in atk_scores if isinstance(s, dict) and s.get("winner")),
                        "n_errors": n_errors,
                        "elapsed_s": round(elapsed, 1),
                    }
                    conditions_done += 1
                    logger.info(f"  [{model_id}][{ds}] {atk_name}: asr={asr:.3f}, errors={n_errors}, {elapsed:.0f}s")
                except Exception as e:
                    logger.error(f"  [{model_id}][{ds}] {atk_name}: FAILED - {e}")
                    traceback.print_exc()
                    atk_result = {
                        "condition": atk_name,
                        "scores": [],
                        "asr": None,
                        "n_samples": 0,
                        "n_errors": -1,
                        "error": str(e),
                    }
                save_condition_result(model_id, ds, atk_name, atk_result)

            ds_results[atk_name] = {
                "asr": atk_result.get("asr"),
                "n_samples": atk_result.get("n_samples", 0),
                "n_errors": atk_result.get("n_errors", 0),
            }

        model_results[ds] = ds_results

    model_elapsed = time.time() - model_t0
    logger.info(f"=== [{model_id}] DONE: {conditions_done} new, {model_elapsed/60:.1f}min ===")
    return model_results


def main():
    logger.info(f"Plan 001 Step 1: Throttled {'(DRY RUN)' if DRY_RUN else '(FULL RUN)'}")
    logger.info(f"  Models: {len(MODEL_IDS)}, Datasets: {len(DATASETS)}, "
                f"Conditions: {len(CONDITIONS)}, Samples/cond: {N_SAMPLES}")
    logger.info(f"  Global concurrent={GLOBAL_CONCURRENT}, {PER_MODEL_WORKERS} workers/model, "
                f"max_retries={MAX_RETRIES}")

    SCORES_DIR.mkdir(parents=True, exist_ok=True)
    all_pairs = load_pairs()

    n_total = len(MODEL_IDS) * len(DATASETS) * len(CONDITIONS)
    n_done = sum(1 for m in MODEL_IDS for ds in DATASETS for c in CONDITIONS if is_done(m, ds, c))
    logger.info(f"  Progress: {n_done}/{n_total} done, {n_total - n_done} remaining")

    if n_done == n_total:
        logger.info("All done.")
        return

    remaining = {m: sum(1 for ds in DATASETS for c in CONDITIONS if not is_done(m, ds, c))
                 for m in MODEL_IDS}
    sorted_models = sorted(MODEL_IDS, key=lambda m: remaining[m], reverse=True)
    logger.info("  Launch order: " + ", ".join(f"{m}({remaining[m]})" for m in sorted_models))

    all_model_results = {}
    t_start = time.time()

    with ThreadPoolExecutor(max_workers=len(MODEL_IDS)) as pool:
        future_to_model = {
            pool.submit(run_model, model_id, all_pairs): model_id
            for model_id in sorted_models
        }
        for future in as_completed(future_to_model):
            model_id = future_to_model[future]
            try:
                result = future.result()
                all_model_results[model_id] = result
                elapsed = time.time() - t_start
                logger.info(f">>> {model_id} completed at {elapsed/60:.1f}min")
            except Exception as e:
                logger.error(f"=== {model_id} CRASHED: {e} ===")
                traceback.print_exc()
                all_model_results[model_id] = {"error": str(e)}

    total_elapsed = time.time() - t_start

    total_calls = 0
    for model_id, ds_results in all_model_results.items():
        if isinstance(ds_results, dict) and "error" in ds_results:
            continue
        for ds, cond_results in ds_results.items():
            for cond, info in cond_results.items():
                total_calls += info.get("n_samples", 0)

    summary = {
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "dry_run": DRY_RUN,
        "n_samples_per_condition": N_SAMPLES,
        "concurrency": f"global={GLOBAL_CONCURRENT}, {PER_MODEL_WORKERS}/model",
        "models": all_model_results,
        "total_api_calls": total_calls,
        "runtime_minutes": round(total_elapsed / 60, 1),
    }
    summary_path = RESULTS_DIR / "step1_api_scoring_summary.json"
    with open(summary_path, "w") as f:
        json.dump(summary, f, indent=2, ensure_ascii=False)
    logger.info(f"Summary: {summary_path}")
    logger.info(f"Total: {total_elapsed/60:.1f}min, {total_calls} API calls")

    print("\n" + "=" * 80)
    print("RESULTS SUMMARY")
    print("=" * 80)
    for model_id in MODEL_IDS:
        ds_results = all_model_results.get(model_id, {})
        if isinstance(ds_results, dict) and "error" in ds_results:
            print(f"\n{model_id}: ERROR - {ds_results['error']}")
            continue
        print(f"\n{model_id}:")
        for ds in DATASETS:
            if ds not in ds_results:
                continue
            conds = ds_results[ds]
            clean_acc = conds.get("clean", {}).get("accuracy", "N/A")
            print(f"  {ds}: clean_acc={clean_acc}", end="")
            for atk in ATTACK_NAMES:
                asr = conds.get(atk, {}).get("asr", "N/A")
                if isinstance(asr, float):
                    print(f"  {atk}={asr:.3f}", end="")
                else:
                    print(f"  {atk}={asr}", end="")
            print()
    print("=" * 80)


if __name__ == "__main__":
    main()
